import React from "react";

class RelatedServices extends React.Component {
  render() {
    const services = [
      {
        name: "نور درمانی LED",
        time: "۳۰ دقیقه",
        price: "از ۸۵۰٬۰۰۰ تومان",
        className: "sky",
      },
      {
        name: "لایه‌برداری شیمیایی",
        time: "۴۵ دقیقه",
        price: "از ۱٬۲۰۰٬۰۰۰ تومان",
        className: "sage",
      },
      {
        name: "میکرونیدلینگ",
        time: "۴۵ دقیقه",
        price: "از ۱٬۱۰۰٬۰۰۰ تومان",
        className: "rose",
      },
    ];

    return (
      <>
        <h3 className="detail-h2">
          خدمات مرتبط
        </h3>

        <div className="rel-scroll">
          {services.map((service, index) => (
            <div className="rel-card" key={index}>
              <div
                className={`rel-img ${service.className}`}
              >
                <svg
                  width="26"
                  height="26"
                  viewBox="0 0 24 24"
                  fill="none"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                >
                  <circle cx="12" cy="12" r="4" />

                  <path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2" />
                </svg>
              </div>

              <div className="rel-name">
                {service.name}
              </div>

              <div className="rel-meta">
                {service.time}
              </div>

              <div className="rel-price">
                {service.price}
              </div>
            </div>
          ))}
        </div>
      </>
    );
  }
}

export default RelatedServices;
